class CalculadoraDeImposto {
  calcular(produto, estrategia) {
    return estrategia.aplicar(produto);
  }
}

class ImpostoEstadual {
  aplicar(produto) {
    return produto.valor * 0.18;
  }
}

class ImpostoFederal {
  aplicar(produto) {
    return produto.valor * 0.12;
  }
}
